from docx import Document
from docx.oxml.ns import qn

doc = Document\("/Users/katiegreeley/Desktop/2026 SUPP files/2026 SUPP Template Report and Appendices.docx"\)

for i in range\(56, 63\):
    if i >= len\(doc.tables\): break
    table = doc.tables[i]
    print\(f"\\n=== Template Table {i}: {len\(table.columns\)}x{len\(table.rows\)} ==="\)
    for r_idx, row in enumerate\(table.rows\):
        for c_idx, cell in enumerate\(row.cells\):
            texts = []
            for t in cell._tc.iter\(qn\('w:t'\)\):
                if t.text: texts.append\(t.text\)
            raw_text = ''.join\(texts\).strip\(\)
            if raw_text:
                print\(f"  [{r_idx},{c_idx}]: {repr\(raw_text[:120]\)}"\)
EOF)
